package org.jlinalg.enrichment;

import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.jupiter.api.Test;

class FumaExpressionPreparationTest {
    private static final Runnable CHECK=()->{};
    private static FumaExpressionPreparation.Frame frame(){return FumaExpressionPreparation.frame(List.of("s1","s2","s3"),List.of(new FumaExpressionPreparation.Sample("s3","B"),new FumaExpressionPreparation.Sample("s1","A"),new FumaExpressionPreparation.Sample("s2","A")),List.of("B","A"),false,FumaExpressionPreparation.Limits.defaults(),CHECK);}
    @Test void documentedCapLogAndSampleCenteredAveragesUseExplicitLabelOrder(){var r=FumaExpressionPreparation.prepare("ENSG1.7",new double[]{0,3,100},frame(),CHECK);double l=StrictMath.log(51)/StrictMath.log(2),center=(2+l)/3;assertEquals("ENSG1.7",r.gene());assertEquals(FumaExpressionPreparation.Disposition.RETAINED,r.disposition());assertArrayEquals(new double[]{100,1.5},r.rawMeans());assertArrayEquals(new double[]{l,1},r.log2Means(),1e-15);assertArrayEquals(new double[]{l-center,1-center},r.centeredMeans(),1e-15);assertEquals(center,r.sampleMeanLog2(),1e-15);assertEquals((l+1)/2,r.labelMeanLog2(),1e-15);assertNotEquals(r.sampleMeanLog2(),r.labelMeanLog2());assertEquals(1,r.cappedSelectedValues());}
    @Test void eligibilityUsesRawMeansBeforeCapOrLogAndStrictGreaterThanOne(){var f=frame();assertEquals(FumaExpressionPreparation.Disposition.NOT_EXPRESSED,FumaExpressionPreparation.prepare("tie",new double[]{0,2,1},f,CHECK).disposition());assertEquals(FumaExpressionPreparation.Disposition.RETAINED,FumaExpressionPreparation.prepare("above",new double[]{0,2,Math.nextUp(1.)},f,CHECK).disposition());assertEquals(FumaExpressionPreparation.Disposition.NOT_EXPRESSED,FumaExpressionPreparation.prepare("below",new double[]{0,2,Math.nextDown(1.)},f,CHECK).disposition());var r=FumaExpressionPreparation.prepare("raw",new double[]{0,100,0},f,CHECK);assertEquals(50,r.rawMeans()[1]);assertEquals(1,r.cappedSelectedValues());assertEquals(StrictMath.log(51)/StrictMath.log(2)/2,r.log2Means()[1]);}
    @Test void sampleSelectionIsExplicitAndDoesNotUseUnselectedValues(){var f=FumaExpressionPreparation.frame(List.of("s0","s1","s2"),List.of(new FumaExpressionPreparation.Sample("s2","B"),new FumaExpressionPreparation.Sample("s0","A")),List.of("A","B"),true,FumaExpressionPreparation.Limits.defaults(),CHECK);assertArrayEquals(new int[]{0,2},f.selectedIndices());var r=FumaExpressionPreparation.prepare("G",new double[]{0,100000,0},f,CHECK);assertEquals(FumaExpressionPreparation.Disposition.NOT_EXPRESSED,r.disposition());assertEquals(0,r.cappedSelectedValues());assertArrayEquals(new double[]{0,0},r.log2Means());assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.prepare("G",new double[]{0,Double.NaN,0},f,CHECK));}
    @Test void immutableFrameAndResultsDoNotRetainCallerArraysOrLists(){var ids=new ArrayList<>(List.of("a","b"));var groups=new ArrayList<>(List.of("X","Y"));var f=FumaExpressionPreparation.frame(ids,List.of(new FumaExpressionPreparation.Sample("a","X"),new FumaExpressionPreparation.Sample("b","Y")),groups,false,FumaExpressionPreparation.Limits.defaults(),CHECK);ids.set(0,"changed");groups.set(0,"changed");f.selectedIndices()[0]=999;f.labelCounts()[0]=999;double[] raw={3,7};var r=FumaExpressionPreparation.prepare("G",raw,f,CHECK);assertArrayEquals(new double[]{3,7},raw);raw[0]=999;r.log2Means()[0]=999;r.rawMeans()[0]=999;assertEquals(2,r.log2Means()[0]);assertEquals(3,r.rawMeans()[0]);assertEquals(List.of("a","b"),f.inputSamples());assertThrows(UnsupportedOperationException.class,()->f.labels().add("Z"));}
    @Test void capIncludesOnlyStrictlyGreaterThanFifty(){var r=FumaExpressionPreparation.prepare("G",new double[]{Math.nextDown(50.),50,Math.nextUp(50.)},frame(),CHECK);assertEquals(1,r.cappedSelectedValues());assertEquals(r.log2Means()[0],r.log2Means()[1],2e-15);}
    @Test void constantExpressionIsValidForPreparationWithoutInventingATest(){var r=FumaExpressionPreparation.prepare("constant",new double[]{3,3,3},frame(),CHECK);assertEquals(FumaExpressionPreparation.Disposition.RETAINED,r.disposition());assertArrayEquals(new double[]{2,2},r.log2Means());assertArrayEquals(new double[]{0,0},r.centeredMeans());assertEquals(2,r.labelMeanLog2());}
    @Test void finiteExtremeRawMeansAvoidOverflowAndTinyPseudocountRoundingIsExplicit(){var r=FumaExpressionPreparation.prepare("large",new double[]{Double.MAX_VALUE,Double.MAX_VALUE,Double.MAX_VALUE},frame(),CHECK);assertArrayEquals(new double[]{Double.MAX_VALUE,Double.MAX_VALUE},r.rawMeans());assertEquals(3,r.cappedSelectedValues());assertTrue(Double.isFinite(r.sampleMeanLog2()));var tiny=FumaExpressionPreparation.prepare("small",new double[]{Double.MIN_VALUE,0,0},frame(),CHECK);assertArrayEquals(new double[]{0,0},tiny.log2Means());assertEquals(FumaExpressionPreparation.Disposition.NOT_EXPRESSED,tiny.disposition());}
    @Test void invalidCompleteFramesRejectUnknownDuplicateAndUnusedLabels(){var l=FumaExpressionPreparation.Limits.defaults();var a=new FumaExpressionPreparation.Sample("s1","A");assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s1"),List.of(a),List.of("A","B"),true,l,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s2"),List.of(a,a),List.of("A","B"),true,l,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s2"),List.of(a,new FumaExpressionPreparation.Sample("absent","B")),List.of("A","B"),true,l,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s2"),List.of(a,new FumaExpressionPreparation.Sample("s2","C")),List.of("A","B"),true,l,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s2"),List.of(a),List.of("A","B"),true,l,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("s1","s2"),List.of(a,new FumaExpressionPreparation.Sample("s2","B")),List.of("A","A"),false,l,CHECK));}
    @Test void missingOrNegativeValuesAndMismatchedRowsNeverProducePreparedOutput(){var f=frame();for(double v:new double[]{-1,Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY})assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.prepare("G",new double[]{0,v,3},f,CHECK));assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.prepare("G",new double[]{0,1},f,CHECK));for(String id:List.of("","a b","a\tb"))assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.prepare(id,new double[]{0,1,2},f,CHECK));}
    @Test void capacitiesAndCancellationFailWithoutAPrefixValue(){assertThrows(IllegalArgumentException.class,()->FumaExpressionPreparation.frame(List.of("a","b"),List.of(new FumaExpressionPreparation.Sample("a","A"),new FumaExpressionPreparation.Sample("b","B")),List.of("A","B"),false,new FumaExpressionPreparation.Limits(2,2,65536),CHECK));var f=frame();var expected=new IllegalStateException("cancel");assertSame(expected,assertThrows(IllegalStateException.class,()->FumaExpressionPreparation.prepare("G",new double[]{0,1,2},f,()->{throw expected;})));}
    @Test void randomRowsMatchDirectIndependentMeansAndWeightedCenter(){var random=new Random(1759);for(int trial=0;trial<200;trial++){double[] v=new double[3];for(int i=0;i<3;i++)v[i]=random.nextDouble()*100;var r=FumaExpressionPreparation.prepare("G",v,frame(),CHECK);double x=Math.log(Math.min(v[0],50)+1)/Math.log(2),y=Math.log(Math.min(v[1],50)+1)/Math.log(2),z=Math.log(Math.min(v[2],50)+1)/Math.log(2),c=(x+y+z)/3;assertArrayEquals(new double[]{v[2],(v[0]+v[1])/2},r.rawMeans(),3e-14);assertArrayEquals(new double[]{z,(x+y)/2},r.log2Means(),3e-15);assertArrayEquals(new double[]{z-c,((x-c)+(y-c))/2},r.centeredMeans(),3e-15);assertEquals(0,r.centeredMeans()[0]+2*r.centeredMeans()[1],4e-15);}}
}
